Monte Carlo: offset of a resistor divider with 1% resistors
.param rnom=10k
V1 a 0 2
R1 a b {agauss(rnom, 0.01*rnom, 1)}
R2 b 0 {agauss(rnom, 0.01*rnom, 1)}
.control
  setseed 7
  let runs = 500
  let vb = vector(runs)
  let k = 0
  while k < runs
    reset
    op
    let vb[k] = v(b)
    let k = k + 1
  end
  let mu = mean(vb)
  let sigma = sqrt(mean((vb - mu)^2))
  print mu sigma
  let lo = vecmin(vb)
  let hi = vecmax(vb)
  print lo hi
  wrdata mc-vb.txt vb
.endc
.end
